const $=id=>document.getElementById(id),money=n=>'€'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={budget:1500,expenses:[{name:'파리의 작은 비스트로',amount:48,category:'식비'},{name:'공항에서 숙소까지',amount:25,category:'교통'},{name:'마레 지구 기념품',amount:85,category:'쇼핑'},{name:'센 강 근처의 숙소',amount:240,category:'숙박'},{name:'미술관 관람',amount:22,category:'관광'}],receipts:[]};try{const saved=JSON.parse(localStorage.getItem('bonjour-finance-v1'));if(saved&&Array.isArray(saved.expenses)&&Array.isArray(saved.receipts)&&Number.isFinite(saved.budget))state=saved;}catch{}function save(){try{localStorage.setItem('bonjour-finance-v1',JSON.stringify(state));}catch{}}
function tab(name){document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===name);b.setAttribute('aria-current',b.dataset.tab===name?'page':'false')});window.scrollTo({top:0,behavior:'smooth'});}document.querySelectorAll('[data-tab],[data-go]').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab||b.dataset.go)));
if(state.trip){$('depart').value=state.trip.depart;$('return').value=state.trip.return;$('has-card').value=state.trip.hasCard;$('card').value=state.trip.card;$('card-label').hidden=state.trip.hasCard==='no';}
$('has-card').onchange=()=>{$('card-label').hidden=$('has-card').value==='no';$('card-results').innerHTML='';};$('setup').onsubmit=e=>{e.preventDefault();if($('return').value<$('depart').value){$('setup-msg').textContent='귀국일은 출발일 이후로 선택해 주세요.';return;}state.trip={depart:$('depart').value,return:$('return').value,hasCard:$('has-card').value,card:$('card').value};save();const days=Math.round((new Date($('return').value)-new Date($('depart').value))/86400000)+1;$('setup-msg').textContent=`${days}일간의 프랑스 여행을 준비하고 있어요.`;const yes=$('has-card').value==='yes';const rows=yes?[['해외결제 수수료','유로 결제 수수료와 면제 조건을 확인해 주세요.'],['유로 충전·잔액','충전 가능 시간, 환전 조건과 잔액을 확인해 주세요.'],['현지 ATM 인출','해외 인출 가능 여부, 한도와 현지 수수료를 확인해 주세요.']]:[['하나 트래블로그','유로 충전 조건 · 해외결제 · ATM 인출 조건 비교'],['트래블월렛','지원 통화 · 충전 한도 · 인출 조건 비교'],['기존 해외결제 카드','국제 브랜드 · 해외 사용 설정 · 수수료 비교']];$('card-results').innerHTML=`<div class="card"><span class="badge">${yes?'카드 확인 가이드':'카드 비교 후보 · 추천 순위 아님'}</span><h3 style="margin-top:17px">${yes?esc($('card').value)+'에서 확인할 3가지':'나에게 맞는 카드를 비교해 보세요'}</h3>${rows.map(([a,b])=>`<div class="result-row"><div><b>${a}</b><p>${b}</p></div><span>↗</span></div>`).join('')}<small>실제 혜택 데이터는 연동되지 않았습니다. 카드사 약관에서 확인해 주세요.</small></div>`;$('card-results').scrollIntoView({behavior:'smooth',block:'nearest'});};
function atm(){const shortage=Math.max(0,Math.round((+$('needed').value-+$('cash').value)*100)/100);if(!shortage){$('atm-results').innerHTML='<span class="badge">준비 완료</span><h3 style="margin-top:20px">추가 현금이 필요하지 않아요.</h3><p>보유한 현금으로 필요한 금액을 충당할 수 있어요.</p>';return;}const offset=$('location').selectedIndex*3,candidates=[{name:'은행 ATM A',type:'atm',walk:4+offset,fee:3},{name:'은행 ATM B',type:'atm',walk:10+offset,fee:1.5},{name:'환전소 C',type:'exchange',walk:7+offset,fee:6}].filter(c=>c.walk<=+$('walk').value&&($('atm-card').value==='yes'||c.type!=='atm')).sort((a,b)=>(a.fee+a.walk*.2)-(b.fee+b.walk*.2));$('atm-results').innerHTML=`<div class="eyebrow">현금 부족액</div><h2 style="font-size:34px">${money(shortage)}</h2><small>가정 수수료 + 도보 1분당 0.2점으로 비교합니다.</small>${candidates.length?candidates.map((c,i)=>`<div class="result-row"><div><b>${c.name}</b> ${i===0?'<span class="badge">데모 비교 1순위</span>':''}<p>${esc($('location').value)} · 도보 ${c.walk}분<br>${c.type==='atm'?'인출 가능한 카드 필요':'환전용 현금·통화 및 거래 조건 확인 필요'}</p></div><div><strong>${money(c.fee)}</strong><p>가정 수수료</p></div></div>`).join(''):'<p class="empty">조건에 맞는 후보가 없어요.<br>도보 범위를 늘리거나 카드 조건을 확인해 주세요.</p>'}`;}$('atm-form').onsubmit=e=>{e.preventDefault();atm();};atm();
function receipts(){const groups={};state.receipts.forEach((r,i)=>{const k=r.store+'|'+r.date;if(!groups[k])groups[k]={...r,sum:0,unknown:false,items:[]};groups[k].sum=Math.round((groups[k].sum+r.amount)*100)/100;groups[k].unknown ||=r.eligible!=='yes';groups[k].items.push(i);});$('receipts').innerHTML=Object.values(groups).map(g=>{const met=g.sum>100.01,need=Math.max(0,100.02-g.sum);return `<div class="result-row"><div><b>${esc(g.store)}</b><p>${esc(g.date)} · ${g.items.length}개 영수증</p><strong>${money(g.sum)}</strong><p>${g.unknown?'환급 요건 확인이 필요해요. 예상액 산출을 보류합니다.':met?'시연용 예상 환급액 '+money(Math.round(g.sum*.12*100)/100):'가정 기준까지 '+money(need)+' 더 필요해요.'}</p><small>시연 기준: 동일 매장·같은 날 €100.01 초과</small></div><button class="delete" data-receipt="${g.items.join(',')}" aria-label="${esc(g.store)} 영수증 묶음 삭제">삭제</button></div>`;}).join('')||'<p class="empty">아직 등록한 영수증이 없어요.<br>첫 쇼핑의 기록을 남겨 보세요.</p>';document.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>{const ids=b.dataset.receipt.split(',').map(Number);state.receipts=state.receipts.filter((_,i)=>!ids.includes(i));save();receipts();});}$('tax-form').onsubmit=e=>{e.preventDefault();if(!$('store').value.trim()){$('store').setCustomValidity('매장명을 입력해 주세요.');$('store').reportValidity();return;}state.receipts.push({store:$('store').value.trim(),date:$('purchase-date').value,amount:+$('purchase-amount').value,eligible:$('eligible').value});save();receipts();$('store').value='';$('purchase-amount').value='';$('receipt-file').value='';};receipts();
const colors={'식비':'#294e3e','교통':'#b5cd8d','쇼핑':'#d9bc83','숙박':'#6c8e73','관광':'#c7d8bd','기타':'#a3aaa0'};function budget(){const total=Math.round(state.expenses.reduce((s,e)=>s+e.amount,0)*100)/100,remaining=state.budget-total;$('total').textContent=money(total);$('chart-total').textContent=money(total);$('remaining').textContent=money(Math.abs(remaining));$('remain-label').textContent=remaining<0?'예산 초과':'남은 예산';let cumulative=0,gradient=[];$('legend').innerHTML=Object.entries(colors).map(([cat,color])=>{const amount=state.expenses.filter(e=>e.category===cat).reduce((s,e)=>s+e.amount,0),pct=total?amount/total*100:0;gradient.push(`${color} ${cumulative}% ${cumulative+pct}%`);cumulative+=pct;return `<div class="legend-row"><span class="dot" style="background:${color}"></span>${cat}<strong>${pct.toFixed(0)}%</strong></div>`;}).join('');$('donut').style.background=total?`conic-gradient(${gradient.join(',')})`:'#e8ece3';$('expenses').innerHTML=state.expenses.map((e,i)=>`<div class="result-row"><div><b>${esc(e.name)}</b><p>${esc(e.category)}</p></div><div><strong>${money(e.amount)}</strong><button class="delete" data-expense="${i}" aria-label="${esc(e.name)} 삭제">×</button></div></div>`).join('')||'<p class="empty">아직 기록된 지출이 없어요.</p>';document.querySelectorAll('[data-expense]').forEach(b=>b.onclick=()=>{state.expenses.splice(+b.dataset.expense,1);save();budget();});}$('budget-input').value=state.budget;$('budget-input').oninput=()=>{if($('budget-input').value!==''&&$('budget-input').validity.valid){state.budget=+$('budget-input').value;save();budget();}};$('expense-form').onsubmit=e=>{e.preventDefault();if(!$('expense-name').value.trim()){$('expense-name').setCustomValidity('지출 항목을 입력해 주세요.');$('expense-name').reportValidity();return;}state.expenses.push({name:$('expense-name').value.trim(),amount:+$('expense-amount').value,category:$('category').value});save();budget();$('expense-name').value='';$('expense-amount').value='';};$('clear-expenses').onclick=()=>$('clear-confirm').hidden=false;$('cancel-clear').onclick=()=>$('clear-confirm').hidden=true;$('confirm-clear').onclick=()=>{state.expenses=[];save();budget();$('clear-confirm').hidden=true;};budget();
function chatOpen(open){$('chat').hidden=!open;$('chat-toggle').setAttribute('aria-expanded',String(open));if(open)$('chat-input').focus();}$('chat-toggle').onclick=()=>chatOpen($('chat').hidden);$('chat-close').onclick=()=>chatOpen(false);$('chat-form').onsubmit=e=>{e.preventDefault();const q=$('chat-input').value.trim();if(!q)return;let answer='프랑스 여행 금융 질문만 도와드릴 수 있어요. 카드, 결제, ATM, 환전, 택스리펀, 교통 결제, 가계부 중에서 질문해 주세요.';if(/카드|결제|수수료/.test(q))answer='보유 카드의 해외 사용 설정, 유로 결제 수수료, ATM 인출 조건을 먼저 확인해 주세요. 「나의 여행」에서 카드에 맞는 확인 항목을 볼 수 있어요. 실제 혜택은 카드사 약관 확인이 필요해요.';if(/현금|ATM|atm|환전|인출/.test(q))answer='필요 현금에서 보유 현금을 빼면 추가 확보할 금액을 알 수 있어요. 「환전·ATM」에서 인출 카드와 도보 조건을 선택해 보세요. 표시된 장소와 수수료는 가상 데이터예요.';if(/환급|택스|영수증/.test(q))answer='「택스리펀」에 같은 매장·같은 날 구매한 영수증을 입력해 보세요. 금액 외에도 거주 요건, 참여 매장, 대상 상품과 출국 확인 등이 필요해요. 12%는 시연용 가정이며 실제 환급률이 아니에요.';if(/예산|가계부|지출/.test(q))answer='「여행 가계부」에서 예산을 설정하고 지출을 추가하면 사용액과 남은 예산을 계산해요. 기록은 이 브라우저에 저장되며 카드 이용 내역은 자동 연결되지 않아요.';if(/교통|지하철|RATP|나비고/.test(q))answer='파리 교통 준비에는 Île-de-France Mobilités, Bonjour RATP를 확인해 보세요. 교통권 구매와 결제 조건은 각 공식 앱에서 확인해 주세요.';const user=document.createElement('p');user.className='user';user.textContent=q;const bot=document.createElement('p');bot.textContent=answer;$('chat-messages').append(user,bot);$('chat-input').value='';$('chat-messages').scrollTop=$('chat-messages').scrollHeight;};

['store','expense-name'].forEach(id=>$(id).addEventListener('input',()=>$(id).setCustomValidity('')));
